package auth

import (
	"github.com/washsky/mygpt-test/internal/ui"
	"io"
	"net/http"
)

func (s *Service) page(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("Cache-Control", "no-store")
	w.Header().Set("Content-Security-Policy", "default-src 'self'; style-src 'self' 'unsafe-inline'; script-src 'self' 'unsafe-inline'; object-src 'none'; base-uri 'none'; frame-ancestors 'none'")
	_, _ = io.WriteString(w, accountPage)
}

const accountPage = `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>账户 · 我的工作空间</title>` + ui.Head + `<style>main{max-width:760px;margin:32px auto;padding:0 16px}.card{padding:24px;margin:18px 0}form{display:grid;gap:10px}input,button{padding:10px;border:1px solid var(--line);border-radius:8px}label{display:grid;gap:5px}.row{display:flex;gap:12px;flex-wrap:wrap}.message{white-space:pre-wrap;overflow-wrap:anywhere;color:var(--accent)}.user-row{display:flex;align-items:center;justify-content:space-between;gap:12px;border-top:1px solid var(--line);padding:12px 0}</style></head><body>` + ui.Nav + `<main><h1>账户</h1><p>登录后使用固定身份发表内容，并管理自己的帖子与回复。也可以<a href="/">继续以访客使用</a>。</p><p id="status" role="status" class="message">正在读取账户信息…</p>
<section id="signed-out" hidden><div class="card"><h2>登录</h2><form id="login"><label>用户名<input name="username" autocomplete="username" maxlength="32" required></label><label>密码<input name="password" type="password" autocomplete="current-password" maxlength="72" required></label><button class="primary">登录</button></form></div><div id="registration" class="card" hidden><h2 id="registration-title">注册账户</h2><p id="registration-note" class="muted"></p><p class="muted">用户名 3–32 位字母、数字、下划线或短横线；密码 12–72 字节。用户名不区分大小写。</p><form id="register"><label>用户名<input name="username" autocomplete="username" minlength="3" maxlength="32" pattern="[A-Za-z0-9][A-Za-z0-9_-]{2,31}" required></label><label>密码<input name="password" type="password" autocomplete="new-password" minlength="12" maxlength="72" required></label><label>确认密码<input name="confirm" type="password" autocomplete="new-password" minlength="12" maxlength="72" required></label><button>注册</button></form></div></section>
<section id="signed-in" hidden><div class="card"><h2 id="identity"></h2><div class="row"><a href="/">返回论坛</a><button id="logout" type="button">退出登录</button></div><h3>修改密码</h3><p class="muted">修改后所有设备均需重新登录。</p><form id="password"><label>当前密码<input name="current_password" type="password" autocomplete="current-password" required></label><label>新密码<input name="new_password" type="password" autocomplete="new-password" minlength="12" maxlength="72" required></label><label>确认新密码<input name="confirm" type="password" autocomplete="new-password" minlength="12" maxlength="72" required></label><button>修改密码</button></form></div></section>
<section id="management" class="card" hidden><h2>用户管理</h2><p class="muted">停用普通用户会撤销其所有登录会话，已有内容继续保留。</p><div id="users"></div></section></main>` + ui.Foot + `<script>
(()=>{const $=q=>document.querySelector(q),status=$('#status');let current;
async function api(path,method='GET',body){const response=await fetch(path,{method,headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});if(!response.ok)throw Error((await response.text()).trim());return response.status===204?null:response.json()}
function update(s){current=s;Object.assign(window.workspaceAuth,s);$('#signed-out').hidden=!!s.user;$('#signed-in').hidden=!s.user;$('#registration').hidden=!s.allow_registration;$('#registration-title').textContent=s.first_registration?'注册首个管理员':'注册账户';$('#registration-note').textContent=s.first_registration?'本站尚无账户，第一个注册成功的账户将自动成为管理员，UID 从 1 开始。':'后续注册账户为普通用户，UID 按注册顺序递增。';$('#management').hidden=s.user?.role!=='admin';$('#workspace-account').textContent=s.user?s.user.username:'登录 / 注册';if(s.user)$('#identity').textContent=s.user.username+' · UID '+s.user.uid+' · '+(s.user.role==='admin'?'管理员':'注册用户')}
async function refresh(){const s=await api('/api/auth/me');update(s);if(s.user?.role==='admin')await users()}
async function users(){const data=await api('/api/auth/users'),container=$('#users');container.replaceChildren();for(const u of data.items){const row=document.createElement('div');row.className='user-row';const name=document.createElement('span');name.textContent=u.username+' · UID '+u.uid+' · '+(u.role==='admin'?'管理员':u.disabled?'已停用':'正常');row.append(name);if(u.role==='member'){const b=document.createElement('button');b.textContent=u.disabled?'启用':'停用';b.type='button';b.onclick=async()=>{b.disabled=true;try{await api('/api/auth/users/'+u.id,'PUT',{disabled:!u.disabled});await users()}catch(e){status.textContent=e.message;b.disabled=false}};row.append(b)}container.append(row)}}
for(const [selector,path] of [['#login','login'],['#register','register'],['#password','password']]){$(selector).onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,values=Object.fromEntries(new FormData(form)),button=event.submitter;if('confirm'in values&&values.confirm!==(values.new_password||values.password)){status.textContent='两次输入的密码不一致';return}delete values.confirm;button.disabled=true;status.textContent='正在处理…';try{const data=await api('/api/auth/'+path,'POST',values);if(path==='login')Object.assign(window.workspaceAuth,{user:data.user,csrf_token:data.csrf_token});if(path==='password')Object.assign(window.workspaceAuth,{user:null,csrf_token:''});form.reset();await refresh();status.textContent=path==='login'?'登录成功，可以返回论坛。':path==='password'?'密码已修改，请重新登录。':(data.message+' · UID '+data.user.uid)}catch(e){status.textContent=e.message}finally{button.disabled=false}}}
$('#logout').onclick=async()=>{try{await api('/api/auth/logout','POST',{});Object.assign(window.workspaceAuth,{user:null,csrf_token:''});await refresh();status.textContent='已退出，可以继续以访客使用。'}catch(e){status.textContent=e.message}};
window.workspaceAuthReady.then(async s=>{update(s);status.textContent=s.user?'当前已登录。':'当前为访客；无需登录也可浏览公开内容。';if(s.user?.role==='admin')await users()}).catch(e=>{status.textContent=e.message});
})();</script></body></html>`
